patch:
diff --git c/lib/string.c w/lib/string.c
index 923969317..76327b51e 100644
--- c/lib/string.c
+++ w/lib/string.c
@@ -46,7 +46,7 @@ int strncasecmp(const char *s1, const char *s2, size_t len)
 		return 0;

 	do {
-		c1 = *s1--;
+		c1 = *s1++;
 		c2 = *s2++;
 		if (!c1 || !c2)
 			break;

diff --git c/lib/string.c w/lib/string.c
index 418efcb35..76327b51e 100644
--- c/lib/string.c
+++ w/lib/string.c
@@ -447,7 +447,7 @@ size_t strcspn(const char *s, const char *reject)
 {
 	const char *p;

-	for (p = s; *p != '\0'; --p) {
+	for (p = s; *p != '\0'; ++p) {
 		if (strchr(reject, *p))
 			break;
 	}
